CREATE TABLE screening_batch_versions(id TEXT PRIMARY KEY,root_id TEXT NOT NULL REFERENCES screening_batch_versions(id) DEFERRABLE INITIALLY DEFERRED,store_id TEXT NOT NULL REFERENCES stores(id),project_id TEXT NOT NULL REFERENCES screening_project_versions(id),project_version_id TEXT NOT NULL REFERENCES screening_project_versions(id),project_sequence INTEGER NOT NULL CHECK(project_sequence>0),customer_profile_prefix INTEGER NOT NULL CHECK(customer_profile_prefix>=0),batch_key TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),sequence INTEGER NOT NULL CHECK(sequence>0),csv_text TEXT NOT NULL,csv_sha256 TEXT NOT NULL,customer_refs_json TEXT NOT NULL,source_note TEXT NOT NULL,record_reason TEXT NOT NULL,created_at TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id),actor_role TEXT NOT NULL CHECK(actor_role IN('manager','reception','professional')),UNIQUE(root_id,revision),UNIQUE(store_id,sequence),UNIQUE(project_id,batch_key,revision));
CREATE VIEW screening_batch_current AS SELECT v.* FROM screening_batch_versions v WHERE revision=(SELECT max(revision) FROM screening_batch_versions WHERE root_id=v.root_id);
CREATE TRIGGER screening_batch_source BEFORE INSERT ON screening_batch_versions BEGIN
 SELECT CASE WHEN NEW.sequence<>coalesce((SELECT max(sequence)+1 FROM screening_batch_versions WHERE store_id=NEW.store_id),1) OR NEW.revision=1 AND (NEW.root_id<>NEW.id OR EXISTS(SELECT 1 FROM screening_batch_versions WHERE project_id=NEW.project_id AND batch_key=NEW.batch_key)) OR NEW.revision>1 AND NOT EXISTS(SELECT 1 FROM screening_batch_current p WHERE p.root_id=NEW.root_id AND p.store_id=NEW.store_id AND p.project_id=NEW.project_id AND p.batch_key=NEW.batch_key AND p.revision+1=NEW.revision) THEN RAISE(ABORT,'screening batch fixed original/root continuous source') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM screening_project_current p JOIN users u ON u.id=NEW.created_by LEFT JOIN user_security s ON s.user_id=u.id WHERE p.root_id=NEW.project_id AND p.id=NEW.project_version_id AND p.store_id=NEW.store_id AND p.action='record' AND p.authorization_status='recorded' AND EXISTS(SELECT 1 FROM users owner LEFT JOIN user_security os ON os.user_id=owner.id WHERE owner.id=p.owner_id AND owner.store_id=p.store_id AND owner.active=1 AND owner.role IN('manager','reception','professional') AND coalesce(os.must_change_password,0)=0) AND u.store_id=NEW.store_id AND u.role=NEW.actor_role AND u.active=1 AND u.role IN('manager','reception','professional') AND coalesce(s.must_change_password,0)=0 AND (u.role='manager' OR p.owner_id=u.id)) THEN RAISE(ABORT,'screening batch current original preparation basis and staff scope') END;
 SELECT CASE WHEN NEW.project_sequence IS NOT (SELECT max(sequence) FROM screening_project_versions WHERE store_id=NEW.store_id) OR NEW.customer_profile_prefix IS NOT (SELECT coalesce(max(rowid),0) FROM customer_profile_versions) THEN RAISE(ABORT,'screening batch captured historical source prefixes') END;
 SELECT CASE WHEN NEW.customer_refs_json IS NOT (SELECT json_group_array(json_object('customer_id',id,'version',version)) FROM (SELECT c.id,(SELECT max(version) FROM customer_profile_versions WHERE customer_id=c.id) version FROM customers c WHERE c.store_id=NEW.store_id ORDER BY c.id)) OR EXISTS(SELECT 1 FROM customers c LEFT JOIN customer_profile_versions v ON v.customer_id=c.id AND v.version=(SELECT max(version) FROM customer_profile_versions WHERE customer_id=c.id) WHERE c.store_id=NEW.store_id AND (v.version IS NULL OR c.name IS NOT v.name OR c.birth_date IS NOT v.birth_date OR c.contact_name IS NOT v.contact_name OR c.phone IS NOT v.phone)) THEN RAISE(ABORT,'screening batch fixed complete original customer profile versions') END;
END;
CREATE TRIGGER screening_batch_text BEFORE INSERT ON screening_batch_versions WHEN length(trim(NEW.batch_key)) NOT BETWEEN 1 AND 160 OR length(NEW.batch_key)>160 OR instr(NEW.batch_key,char(0))>0 OR length(CAST(NEW.csv_text AS BLOB)) NOT BETWEEN 1 AND 262144 OR instr(NEW.csv_text,char(0))>0 OR length(NEW.csv_sha256)<>64 OR NEW.csv_sha256 GLOB '*[^0-9a-f]*' OR length(trim(NEW.source_note)) NOT BETWEEN 1 AND 2000 OR length(NEW.source_note)>2000 OR instr(NEW.source_note,char(0))>0 OR length(trim(NEW.record_reason)) NOT BETWEEN 1 AND 300 OR length(NEW.record_reason)>300 OR instr(NEW.record_reason,char(0))>0 BEGIN SELECT RAISE(ABORT,'screening batch explicit raw source text');END;
CREATE TRIGGER screening_batch_time BEFORE INSERT ON screening_batch_versions WHEN length(NEW.created_at)<>24 OR strftime('%Y-%m-%dT%H:%M:%fZ',NEW.created_at) IS NOT NEW.created_at OR EXISTS(SELECT 1 FROM screening_batch_versions WHERE store_id=NEW.store_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM screening_project_versions WHERE id=NEW.project_version_id AND created_at>NEW.created_at) OR EXISTS(SELECT 1 FROM json_each(NEW.customer_refs_json) r JOIN customer_profile_versions v ON v.customer_id=json_extract(r.value,'$.customer_id') AND v.version=json_extract(r.value,'$.version') WHERE v.created_at>NEW.created_at) BEGIN SELECT RAISE(ABORT,'screening batch historical source time');END;
CREATE TRIGGER screening_batch_no_update BEFORE UPDATE ON screening_batch_versions BEGIN SELECT RAISE(ABORT,'screening batch immutable original CSV');END;
CREATE TRIGGER screening_batch_no_delete BEFORE DELETE ON screening_batch_versions BEGIN SELECT RAISE(ABORT,'screening batch immutable original CSV');END;
